from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import ChassisURI


class ChassisCommon(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_network_adapters_collection(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ChassisURI().network_adapters_collection_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_network_adapters_details(self, check_status=None):
        uri_params = '?$expand=.'  # query parameters
        return self.get_network_adapters_collection(check_status=check_status, query_parameters=uri_params)

    def get_thermal_sensors_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ChassisURI().thermal_sensor_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)

    def get_power_sensors_info(self, check_status=None, query_parameters=''):
        uri_params = query_parameters
        uri = ChassisURI().power_sensor_uri + uri_params
        return self.api_client.send_get_request(uri=uri, check_status=check_status)
